  "Ask first: {mnemo} reads freely but asks before it changes notes or runs sub-agents. Auto: changes and sub-agents go ahead without asking. Read only: it reads and answers, and never changes notes. Saved at once.": "Ερώτηση πρώτα: το {mnemo} διαβάζει ελεύθερα αλλά ρωτά πριν αλλάξει σημειώσεις ή τρέξει υπο-πράκτορες. Αυτόματα: οι αλλαγές και οι υπο-πράκτορες προχωρούν χωρίς ερώτηση. Μόνο ανάγνωση: διαβάζει και απαντά, χωρίς να αλλάζει σημειώσεις. Αποθηκεύεται αμέσως.",
  "Ask privately… nothing here is kept": "Ρώτα ιδιωτικά… τίποτα εδώ δεν κρατιέται",
