  "Browsers signed in to your account. Tap ⋯ to name a device, see its sign-ins or sign it out. Connected agents are not listed here and keep working.": "Browsers συνδεδεμένοι στον λογαριασμό σου. Πάτα ⋯ για να ονομάσεις μια συσκευή, να δεις τις συνδέσεις της ή να την αποσυνδέσεις. Οι συνδεδεμένοι πράκτορες δεν εμφανίζονται εδώ και συνεχίζουν να δουλεύουν.",
