  "Button does nothing? Choose <b>Copy setup instead</b> and paste it into <code>~/.cursor/mcp.json</code> (create the file when missing).": "Το κουμπί δεν κάνει τίποτα; Διάλεξε <b>Αντιγραφή ρύθμισης αντί αυτού</b> και επικόλλησέ την στο <code>~/.cursor/mcp.json</code> (δημιούργησε το αρχείο αν λείπει).",
  "Button does nothing? Choose <b>Copy setup instead</b>, run <b>MCP: Open User Configuration</b> from the Command Palette and paste it there. VS Code uses <code>servers</code>, not <code>mcpServers</code>.": "Το κουμπί δεν κάνει τίποτα; Διάλεξε <b>Αντιγραφή ρύθμισης αντί αυτού</b>, τρέξε <b>MCP: Open User Configuration</b> από την Command Palette και επικόλλησέ την εκεί. Το VS Code χρησιμοποιεί <code>servers</code>, όχι <code>mcpServers</code>.",
  "By": "Από",
