  "Choose a language": "Επιλέξτε γλώσσα",
  "Choose a new password. You can also change the username here.": "Διάλεξε νέο κωδικό. Μπορείς να αλλάξεις κι εδώ το όνομα χρήστη.",
  "Choose between 0.1 and 50 MB": "Διάλεξε από 0,1 έως 50 MB",
  "Choose from many languages in Settings, Appearance, per device. Auto follows your browser.": "Διάλεξε ανάμεσα σε πολλές γλώσσες στις Ρυθμίσεις, Εμφάνιση, ανά συσκευή. Το Αυτόματα ακολουθεί τον browser σου.",
  "Choose your vault folder": "Διάλεξε τον φάκελο του θησαυροφυλακίου σου",
  "Chosen colour": "Επιλεγμένο χρώμα",
  "Chosen when it signs in": "Επιλέγεται όταν συνδεθεί",
  "Claude Desktop (older)": "Claude Desktop (παλαιότερο)",
  "Claude and ChatGPT sign in with your Memora account. Nothing to copy.": "Το Claude και το ChatGPT συνδέονται με τον λογαριασμό σου στο Memora. Δεν χρειάζεται αντιγραφή.",
  "Claude models": "Μοντέλα Claude",
  "Claude signs in over OAuth, so no key is pasted: it gets its own key when you press Allow. Without sign-in, connect it as <b>Other app</b> and send the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Το Claude συνδέεται μέσω OAuth, οπότε δεν επικολλάς κλειδί: παίρνει δικό του κλειδί όταν πατήσεις Να επιτρέπεται. Χωρίς σύνδεση, σύνδεσέ το ως <b>Άλλη εφαρμογή</b> και στείλε την κεφαλίδα <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Claude, ChatGPT, Cursor and more": "Claude, ChatGPT, Cursor και άλλα",
  "Claude, ChatGPT, Cursor and more, each with its own key": "Claude, ChatGPT, Cursor και άλλα, καθένα με δικό του κλειδί",
  "Claude, ChatGPT, Cursor, Codex and others each get their own access, so you can see what each one does.": "Τα Claude, ChatGPT, Cursor, Codex και άλλα παίρνουν το καθένα δική του πρόσβαση, ώστε να βλέπεις τι κάνει το καθένα.",
  "Claude, Cursor, ChatGPT and your own agent share one Memora, reachable from this computer, the local network or the internet": "Τα Claude, Cursor, ChatGPT και ο δικός σου πράκτορας μοιράζονται ένα Memora, προσβάσιμο από αυτόν τον υπολογιστή, το τοπικό δίκτυο ή το internet",
  "Claude, Cursor, ChatGPT and your own scripts read your notes and add to them.": "Το Claude, το Cursor, το ChatGPT και τα δικά σου scripts διαβάζουν τις σημειώσεις σου και προσθέτουν σε αυτές.",
  "Clean up chats": "Καθαρισμός συνομιλιών",
  "Clean up chats…": "Καθαρισμός συνομιλιών…",
  "Clean view": "Καθαρή προβολή",
