  "Clear the tag search": "Εκκαθάριση της αναζήτησης ετικετών",
  "Click <b>Add</b>, then <b>Connect</b>. A Memora page opens: sign in if asked and press <b>Allow</b>.": "Πάτα <b>Προσθήκη</b> και μετά <b>Σύνδεση</b>. Ανοίγει μια σελίδα του Memora: συνδέσου αν σου ζητηθεί και πάτα <b>Να επιτρέπεται</b>.",
  "Click or tick tags to see their notes. Need more, like {example}? Use {button}": "Κάνε κλικ ή τσέκαρε ετικέτες για να δεις τις σημειώσεις τους. Θες κι άλλες, όπως {example}; Χρησιμοποίησε {button}",
