  "Delete {n} notes forever?": "Οριστική διαγραφή {n} σημειώσεων;",
  "Deleted": "Διαγράφηκε",
  "Deleted by {who}": "Διαγράφηκε από {who}",
  "Deleted chats and their messages are gone for good. Your notes are not touched, and a chat that is answering right now is left alone.": "Οι διαγραμμένες συνομιλίες και τα μηνύματά τους χάνονται οριστικά. Οι σημειώσεις σου δεν επηρεάζονται και μια συνομιλία που απαντά αυτή τη στιγμή δεν πειράζεται.",
  "Deleted notes": "Διαγραμμένες σημειώσεις",
  "Deleted notes wait here until you restore them or delete them forever. When you restore, you choose where the note goes: its old folder, another folder or the top level.": "Οι διαγραμμένες σημειώσεις περιμένουν εδώ μέχρι να τις επαναφέρεις ή να τις διαγράψεις οριστικά. Όταν επαναφέρεις, διαλέγεις πού πάει η σημείωση: στον παλιό της φάκελο, σε άλλον φάκελο ή στο ανώτατο επίπεδο.",
  "Deleted notes, ready to restore": "Διαγραμμένες σημειώσεις, έτοιμες για επαναφορά",
  "Deleted or moved to Trash": "Διαγράφηκε ή μετακινήθηκε στον Κάδο",
