  "Done. I tagged 6 notes with #reading and linked 2 of them to {note}.": "Έτοιμο. Έβαλα ετικέτα #reading σε 6 σημειώσεις και συνέδεσα 2 από αυτές με το {note}.",
  "Dot grid": "Πλέγμα κουκκίδων",
