  "Download the {kind} file": "Λήψη του αρχείου {kind}",
  "Drag a card into another folder frame to move the note on disk. Drag a frame by its name to rearrange the board; drop it onto another frame to move the whole folder there. Double-click a title to rename. On touch: drag to pan, pinch to zoom, long-press a card to move it, tap to preview.": "Σύρε μια κάρτα σε άλλο πλαίσιο φακέλου για να μετακινήσεις τη σημείωση στον δίσκο. Σύρε ένα πλαίσιο από το όνομά του για να αναδιατάξεις τον πίνακα· άφησέ το πάνω σε άλλο πλαίσιο για να μετακινήσεις ολόκληρο τον φάκελο εκεί. Διπλό κλικ σε τίτλο για μετονομασία. Σε οθόνη αφής: σύρε για μετακίνηση, τσίμπημα για ζουμ, παρατεταμένο πάτημα σε κάρτα για να τη μετακινήσεις, πάτημα για προεπισκόπηση.",
  "Drag a note here to pin it": "Σύρε μια σημείωση εδώ για να την καρφιτσώσεις",
  "Drag notes or folders here to pin them": "Σύρε σημειώσεις ή φακέλους εδώ για να τους καρφιτσώσεις",
  "Drag notes or folders onto a folder to move them, onto Pinned to pin them.": "Σύρε σημειώσεις ή φακέλους πάνω σε φάκελο για μετακίνηση, ή στα Καρφιτσωμένα για καρφίτσωμα.",
  "Drag notes · double-click to pin · / search · #tag finds tags · F fit · 1 2 3 layouts": "Σύρε σημειώσεις · διπλό κλικ για καρφίτσωμα · / αναζήτηση · #tag βρίσκει ετικέτες · F προσαρμογή · 1 2 3 διατάξεις",
  "Drag to move the folder frame; double-click to rename": "Σύρε για μετακίνηση του πλαισίου φακέλου· διπλό κλικ για μετονομασία",
  "Drag to resize · double-click to reset": "Σύρε για αλλαγή μεγέθους · διπλό κλικ για επαναφορά",
  "Drag to turn · scroll to zoom · click a point to open its note": "Σύρε για περιστροφή · κύλιση για ζουμ · κλικ σε σημείο για άνοιγμα της σημείωσής του",
  "Drag to turn · scroll to zoom · click a point to open its note · / to search · #tag finds tags": "Σύρε για περιστροφή · κύλιση για ζουμ · κλικ σε σημείο για άνοιγμα της σημείωσής του · / για αναζήτηση · #tag βρίσκει ετικέτες",
  "Draw a chart of how many notes I write each week": "Σχεδίασε ένα γράφημα με το πόσες σημειώσεις γράφω κάθε εβδομάδα",
  "Draw this note as a diagram": "Σχεδίασε αυτή τη σημείωση ως διάγραμμα",
  "Drop here to hide": "Άφησέ το εδώ για απόκρυψη",
  "Drop on a folder": "Άφησέ το πάνω σε φάκελο",
  "Duplicated a note": "Αντέγραψε μια σημείωση",
  "Duration": "Διάρκεια",
  "Dusk": "Σούρουπο",
  "Dyslexic": "Δυσλεξίας",
  "Each AI app connects over MCP with its own key and permissions.": "Κάθε εφαρμογή AI συνδέεται μέσω MCP με δικό της κλειδί και δικές της άδειες.",
  "Each AI app you connect is an agent with its own key, so you see what each one does and can turn one off on its own.": "Κάθε εφαρμογή AI που συνδέεις είναι ένας πράκτορας με δικό του κλειδί, ώστε να βλέπεις τι κάνει καθεμία και να απενεργοποιείς μία χωριστά.",
  "Each agent": "Κάθε πράκτορας",
  "Each agent belongs to one app. For another app or device, make a new agent.": "Κάθε πράκτορας ανήκει σε μία εφαρμογή. Για άλλη εφαρμογή ή συσκευή, φτιάξε νέο πράκτορα.",
  "Each agent belongs to one app. To use Memora in another app, create a separate agent for it.": "Κάθε πράκτορας ανήκει σε μία εφαρμογή. Για να χρησιμοποιήσεις το Memora σε άλλη εφαρμογή, δημιούργησε ξεχωριστό πράκτορα.",
  "Each app gets its own key": "Κάθε εφαρμογή παίρνει δικό της κλειδί",
  "Each kind is measured against its own room: its limit when set, else what it uses plus the free disk space{disk}. Empty limit: none.": "Κάθε είδος μετριέται με τον δικό του χώρο: το όριό του όταν υπάρχει, αλλιώς όσο χρησιμοποιεί συν τον ελεύθερο χώρο δίσκου{disk}. Κενό όριο: κανένα.",
  "Each one gets its own key from Memora.": "Καθένα παίρνει δικό του κλειδί από το Memora.",
