  "End every session except this one. Those browsers must sign in again.": "Τερμάτισε κάθε συνεδρία εκτός από αυτήν. Αυτοί οι browsers πρέπει να συνδεθούν ξανά.",
  "End group": "Τέλος ομάδας",
