  "End the session in this browser.": "Τερματισμός της συνεδρίας σε αυτόν τον browser.",
  "Enter a username.": "Γράψε ένα όνομα χρήστη.",
  "Enter an address or a web address first.": "Γράψε πρώτα μια διεύθυνση ή διεύθυνση web.",
  "Enter an address or a web address, then test.": "Γράψε μια διεύθυνση ή διεύθυνση web και μετά δοκίμασε.",
  "Enter the code here": "Γράψε τον κωδικό εδώ",
  "Enter the folder path.": "Γράψε τη διαδρομή του φακέλου.",
