  "Everything, plus switching tools off for everyone and managing other agents. Only for automation you fully trust.": "Τα πάντα, συν την απενεργοποίηση εργαλείων για όλους και τη διαχείριση άλλων πράκτορων. Μόνο για αυτοματισμούς που εμπιστεύεσαι πλήρως.",
  "Exact": "Ακριβές",
