  "Fill in the web address above. Requests sent to it will then be {verb}.": "Συμπλήρωσε παραπάνω τη διεύθυνση web. Τα αιτήματα που στέλνονται σε αυτήν θα είναι: {verb}.",
  "Fill in the {what} above. Requests from it will then be {verb}.": "Συμπλήρωσε παραπάνω το {what}. Τα αιτήματα από αυτό θα είναι: {verb}.",
