  "General": "Γενικά",
  "Get a one-time code on the server": "Πάρε έναν κωδικό μίας χρήσης στον διακομιστή",
  "Get started": "Ξεκίνα",
  "Get to know me from my notes. Look through my vault (recent notes, journals, projects, anything about me) and keep what you learn with remember_owner: who I am, what I work on, how I like answers, what I like. Short, lasting things only, never secrets. Then tell me in a few lines what you kept.": "Γνώρισέ με μέσα από τις σημειώσεις μου. Δες το vault μου (πρόσφατες σημειώσεις, ημερολόγια, έργα, ό,τι αφορά εμένα) και κράτα όσα μαθαίνεις με το remember_owner: ποιος είμαι, με τι ασχολούμαι, πώς μου αρέσουν οι απαντήσεις, τι μου αρέσει. Μόνο σύντομα, διαρκή πράγματα, ποτέ μυστικά. Μετά πες μου σε λίγες γραμμές τι κράτησες.",
  "Gets its own agent key: read and write nodes over MCP": "Παίρνει δικό του κλειδί πράκτορα: ανάγνωση και εγγραφή κόμβων μέσω MCP",
  "Getting started": "Πρώτα βήματα",
