  "Give Claude, Cursor or any MCP app its own key, then let it save what it already knows about you.": "Δώσε στο Claude, στο Cursor ή σε οποιαδήποτε εφαρμογή MCP δικό της κλειδί και άσ' την να αποθηκεύσει ό,τι ήδη ξέρει για σένα.",
  "Give a key read-only access, or let it write too.": "Δώσε σε ένα κλειδί πρόσβαση μόνο ανάγνωσης, ή άσ' το να γράφει κι αυτό.",
  "Give each app or device its own agent. Activity then shows exactly who did what, and you can turn one off without touching the others.": "Δώσε σε κάθε εφαρμογή ή συσκευή δικό της πράκτορα. Έτσι η Δραστηριότητα δείχνει ακριβώς ποιος έκανε τι και μπορείς να απενεργοποιήσεις έναν χωρίς να αγγίξεις τους άλλους.",
  "Give it a name you recognise": "Δώσε ένα όνομα που αναγνωρίζεις",
