  "How much room notes, images and Mnemo chats take, each against its own room. A banner warns when one is almost full.": "Πόσο χώρο πιάνουν οι σημειώσεις, οι εικόνες και οι συνομιλίες του Mnemo, καθένα με τον δικό του χώρο. Ένα banner προειδοποιεί όταν κάτι γεμίζει σχεδόν.",
