  "I find, read, write, tag, link and tidy your notes. No web, no shell: only your vault.": "Βρίσκω, διαβάζω, γράφω, βάζω ετικέτες, συνδέω και τακτοποιώ τις σημειώσεις σου. Χωρίς web, χωρίς shell: μόνο το θησαυροφυλάκιό σου.",
