  "Idle": "Αδρανές",
  "If it's been useful to you, a star on GitHub or telling a friend helps others find it. No worries if not.": "Αν σου φάνηκε χρήσιμο, ένα αστέρι στο GitHub ή ένα λόγο σε έναν φίλο βοηθά κι άλλους να το βρουν. Κανένα πρόβλημα αν όχι.",
  "If you leave, they are kept on this device and offered again when you open the note.": "Αν φύγεις, κρατιούνται σε αυτή τη συσκευή και προσφέρονται ξανά όταν ανοίξεις τη σημείωση.",
