  "Images live beside the notes that show them. Choose how large one may be, and see what notes and images take.": "Οι εικόνες βρίσκονται δίπλα στις σημειώσεις που τις δείχνουν. Διάλεξε πόσο μεγάλη μπορεί να είναι μία και δες τι χώρο πιάνουν σημειώσεις και εικόνες.",
  "Import and export": "Εισαγωγή και εξαγωγή",
