  "In ChatGPT, open <b>Settings → Apps &amp; Connectors → Advanced settings</b> and turn on <b>Developer mode</b>. Then choose <b>Create</b>.": "Στο ChatGPT, άνοιξε <b>Settings → Apps &amp; Connectors → Advanced settings</b> και ενεργοποίησε το <b>Developer mode</b>. Μετά διάλεξε <b>Create</b>.",
  "In Claude (web or desktop), open <b>Settings → Connectors</b> and choose <b>Add custom connector</b>.": "Στο Claude (web ή desktop), άνοιξε <b>Settings → Connectors</b> και διάλεξε <b>Add custom connector</b>.",
  "In Claude Desktop, open <b>Settings → Developer → Edit Config</b>. On newer versions, pick <b>Claude</b> instead.": "Στο Claude Desktop, άνοιξε <b>Settings → Developer → Edit Config</b>. Στις νεότερες εκδόσεις, διάλεξε <b>Claude</b>.",
  "In Windsurf, open <b>Settings → Cascade → MCP servers</b> and choose <b>View raw config</b>.": "Στο Windsurf, άνοιξε <b>Settings → Cascade → MCP servers</b> και διάλεξε <b>View raw config</b>.",
