  "Locks, mentions and assignments so agents do not overwrite each other.": "Κλειδαριές, αναφορές και αναθέσεις ώστε οι πράκτορες να μη γράφουν ο ένας πάνω στον άλλον.",
  "Long enough. A few more characters make it stronger.": "Αρκετά μακρύς. Λίγοι ακόμη χαρακτήρες τον κάνουν ισχυρότερο.",
  "Longer tasks show as a checklist above the message box: not started, in progress, done.": "Οι μεγαλύτερες εργασίες εμφανίζονται ως λίστα ελέγχου πάνω από το πλαίσιο μηνύματος: δεν ξεκίνησε, σε εξέλιξη, τέλος.",
