  "Medium": "Μεσαίο",
  "Medium text": "Μεσαίο κείμενο",
  "Meet Mnemo, your notes agent": "Γνώρισε το Mnemo, τον πράκτορα σημειώσεών σου",
  "Memora address (MCP endpoint)": "Διεύθυνση Memora (endpoint MCP)",
  "Memora already uses this folder.": "Το Memora χρησιμοποιεί ήδη αυτόν τον φάκελο.",
  "Memora by Codrihub Tech": "Memora από την Codrihub Tech",
  "Memora can save notes here": "Το Memora μπορεί να αποθηκεύει σημειώσεις εδώ",
  "Memora checks the folder and asks you to confirm before it switches. Nothing is moved or copied, and you can switch back here. Running in Docker? Use a folder mounted into the container.": "Το Memora ελέγχει τον φάκελο και ζητά επιβεβαίωση πριν αλλάξει. Δεν μετακινείται ούτε αντιγράφεται τίποτα, και μπορείς να γυρίσεις πίσω από εδώ. Τρέχεις σε Docker; Χρησιμοποίησε φάκελο προσαρτημένο στο container.",
  "Memora could not start.": "Το Memora δεν μπόρεσε να ξεκινήσει.",
  "Memora data folder": "Φάκελος δεδομένων Memora",
  "Memora first checks that the new folder exists (or can be created) and that it can save notes there. If the check fails, nothing changes.": "Το Memora ελέγχει πρώτα ότι ο νέος φάκελος υπάρχει (ή μπορεί να δημιουργηθεί) και ότι μπορεί να αποθηκεύει σημειώσεις εκεί. Αν ο έλεγχος αποτύχει, δεν αλλάζει τίποτα.",
  "Memora first checks that the new folder exists and that it can save notes there. If the check fails, nothing changes.": "Το Memora ελέγχει πρώτα ότι ο νέος φάκελος υπάρχει και ότι μπορεί να αποθηκεύει σημειώσεις εκεί. Αν ο έλεγχος αποτύχει, δεν αλλάζει τίποτα.",
  "Memora in your language, Mnemo showing its plan as it works, and you choosing what it may use and see.": "Το Memora στη γλώσσα σου, το Mnemo να δείχνει το πλάνο του καθώς δουλεύει, κι εσύ να διαλέγεις τι μπορεί να χρησιμοποιεί και να βλέπει.",
  "Memora is a notes app your AI apps can use too. You write in it, they read and write the same notes, and you can always see what changed.": "Το Memora είναι μια εφαρμογή σημειώσεων που μπορούν να χρησιμοποιούν και οι εφαρμογές AI σου. Γράφεις εσύ, διαβάζουν και γράφουν στις ίδιες σημειώσεις εκείνες, και βλέπεις πάντα τι άλλαξε.",
  "Memora is free and open source": "Το Memora είναι δωρεάν και ανοιχτού κώδικα",
  "Memora is free and open source. A star helps others find it.": "Το Memora είναι δωρεάν και ανοιχτού κώδικα. Ένα αστέρι βοηθά κι άλλους να το βρουν.",
  "Memora is memory, advanced: built to remember what you and your AI learn, and to remember more the more you use it.": "Το Memora είναι μνήμη, προχωρημένη: φτιαγμένη να θυμάται ό,τι μαθαίνεις εσύ και το AI σου, και να θυμάται περισσότερα όσο το χρησιμοποιείς.",
  "Memora is restarting": "Το Memora επανεκκινείται",
  "Memora is shut down": "Το Memora τερματίστηκε",
  "Memora is still empty. Connect an AI app, send it one prompt, and it saves what it knows about you here, as notes you can read, edit and see in the brain.": "Το Memora είναι ακόμη άδειο. Σύνδεσε μια εφαρμογή AI, στείλε της μία προτροπή, και αποθηκεύει εδώ ό,τι ξέρει για σένα, ως σημειώσεις που διαβάζεις, επεξεργάζεσαι και βλέπεις στον εγκέφαλο.",
  "Memora keeps a list of your tags to suggest them while you type. Refresh it if a tag is missing or out of date.": "Το Memora κρατά μια λίστα με τις ετικέτες σου για να τις προτείνει όσο πληκτρολογείς. Ανανέωσέ τη αν λείπει ή είναι παλιά κάποια ετικέτα.",
  "Memora keeps every version of a note when the vault folder is a git repository. Run {cmd} in the vault folder once (see Configuration, “Version history” in the docs); from then on every change is kept here.": "Το Memora κρατά κάθε έκδοση μιας σημείωσης όταν ο φάκελος του θησαυροφυλακίου είναι αποθετήριο git. Τρέξε {cmd} μία φορά στον φάκελο του θησαυροφυλακίου (δες Configuration, «Version history» στα docs)· από εκεί και πέρα κάθε αλλαγή κρατιέται εδώ.",
  "Memora keeps it in one place:": "Το Memora το κρατά σε ένα μέρος:",
  "Memora saves every note as a plain Markdown file on the machine it runs on. Nothing is locked in: open the files in any editor, back them up, or keep them in Git.": "Το Memora αποθηκεύει κάθε σημείωση ως απλό αρχείο Markdown στο μηχάνημα που τρέχει. Τίποτα δεν είναι κλειδωμένο: άνοιξε τα αρχεία σε οποιονδήποτε επεξεργαστή, κάνε αντίγραφα ασφαλείας ή κράτα τα στο Git.",
  "Memora speaks MCP over streamable HTTP. Apps send the key in the header <code>Authorization: Bearer &lt;key&gt;</code>.": "Το Memora μιλά MCP πάνω από streamable HTTP. Οι εφαρμογές στέλνουν το κλειδί στην κεφαλίδα <code>Authorization: Bearer &lt;key&gt;</code>.",
  "Memora stops on the machine it runs on. Your notes stay safe on disk.": "Το Memora σταματά στο μηχάνημα που τρέχει. Οι σημειώσεις σου μένουν ασφαλείς στον δίσκο.",
  "Memora version": "Έκδοση Memora",
  "Memora v{latest} is available. This server runs v{current}.": "Το Memora v{latest} είναι διαθέσιμο. Αυτός ο διακομιστής τρέχει v{current}.",
  "Memora, open Overview": "Memora, άνοιγμα Επισκόπησης",
  "Memora: a notes vault you host yourself, with an agent that tidies it.": "Memora: ένα θησαυροφυλάκιο σημειώσεων που φιλοξενείς μόνος σου, με έναν πράκτορα που το τακτοποιεί.",
  "Memory used: {used} of {win}": "Μνήμη που χρησιμοποιείται: {used} από {win}",
