  "Mnemo (AI agent)": "Mnemo (πράκτορας AI)",
  "Mnemo button hidden. Show it again from More, Show the Mnemo button.": "Το κουμπί Mnemo κρύφτηκε. Εμφάνισέ το ξανά από το Περισσότερα, Εμφάνιση του κουμπιού Mnemo.",
  "Mnemo goes on without sub-agents": "Το Mnemo συνεχίζει χωρίς υπο-πράκτορες",
  "Mnemo has no model yet: add a provider and its models in Settings, Mnemo": "Το Mnemo δεν έχει ακόμη μοντέλο: πρόσθεσε πάροχο και τα μοντέλα του στις Ρυθμίσεις, Mnemo",
  "Mnemo is built into Memora. Connect your own AI key, then ask in plain words: it finds, writes, tags, links and tidies notes for you.": "Το Mnemo είναι ενσωματωμένο στο Memora. Σύνδεσε το δικό σου κλειδί AI και ρώτα με απλά λόγια: βρίσκει, γράφει, βάζει ετικέτες, συνδέει και τακτοποιεί σημειώσεις για σένα.",
  "Mnemo is still answering in this chat": "Το Mnemo απαντά ακόμη σε αυτή τη συνομιλία",
  "Mnemo is the agent built into Memora. Connect your own AI key and ask in plain words: it keeps your notes in order while your other apps use them.": "Το Mnemo είναι ο πράκτορας που είναι ενσωματωμένος στο Memora. Σύνδεσε το δικό σου κλειδί AI και ζήτα του με απλά λόγια: κρατά τις σημειώσεις σου σε τάξη ενώ οι άλλες εφαρμογές σου τις χρησιμοποιούν.",
  "Mnemo keeps at most {n} providers; delete one first": "Το Mnemo κρατά το πολύ {n} παρόχους· διέγραψε πρώτα έναν",
  "Mnemo stopped after {n} steps; say \"continue\" to go on.": "Το Mnemo σταμάτησε μετά από {n} βήματα· πες «συνέχισε» για να προχωρήσει.",
  "Mnemo's plan, live": "Το πλάνο του Mnemo, ζωντανά",
