  "Not created yet. Click to create it.": "Δεν έχει δημιουργηθεί ακόμη. Κάνε κλικ για δημιουργία.",
  "Not done: Mnemo is in Ask first mode, so changes wait for the owner's OK. Ask with ask_owner (say what you will change; give an option with approve: true such as \"Yes, go ahead\"), then make the change after they approve.": "Δεν έγινε: το Mnemo είναι σε λειτουργία Ερώτηση πρώτα, οπότε οι αλλαγές περιμένουν το OK του ιδιοκτήτη. Ρώτα με ask_owner (πες τι θα αλλάξεις· δώσε μια επιλογή με approve: true όπως «Ναι, προχώρα»), και κάνε την αλλαγή αφού εγκρίνει.",
  "Not done: Mnemo is in Read only mode, so notes are not changed. Say what you would change; the owner can switch to Ask first or Auto in the chat.": "Δεν έγινε: το Mnemo είναι σε λειτουργία Μόνο ανάγνωση, οπότε οι σημειώσεις δεν αλλάζουν. Πες τι θα άλλαζες· ο ιδιοκτήτης μπορεί να περάσει σε Ερώτηση πρώτα ή Αυτόματα στη συνομιλία.",
  "Not done: the chat is in Ask first mode, so a sub-agent cannot change notes. Say in your answer what should change; Mnemo asks the owner.": "Δεν έγινε: η συνομιλία είναι σε λειτουργία Ερώτηση πρώτα, οπότε ένας υπο-πράκτορας δεν μπορεί να αλλάξει σημειώσεις. Πες στην απάντησή σου τι πρέπει να αλλάξει· το Mnemo ρωτά τον ιδιοκτήτη.",
  "Not done: the owner switched {tool} off for Mnemo (Settings, Mnemo).": "Δεν έγινε: ο ιδιοκτήτης απενεργοποίησε το {tool} για το Mnemo (Ρυθμίσεις, Mnemo).",
  "Not done: the owner switched {tool} off for sub-agents (Settings, Mnemo).": "Δεν έγινε: ο ιδιοκτήτης απενεργοποίησε το {tool} για τους υπο-πράκτορες (Ρυθμίσεις, Mnemo).",
