  "Notes appear as the AI saves them and light up the brain. This page turns into your dashboard when the first note arrives.": "Οι σημειώσεις εμφανίζονται καθώς τις αποθηκεύει το AI και φωτίζουν τον εγκέφαλο. Αυτή η σελίδα γίνεται ο πίνακας ελέγχου σου όταν έρθει η πρώτη σημείωση.",
