  "Off": "Ανενεργό",
  "Off for every AI.": "Ανενεργό για κάθε AI.",
  "Off for every agent": "Ανενεργό για κάθε πράκτορα",
  "Off: its models are hidden in chats": "Ανενεργό: τα μοντέλα του κρύβονται στις συνομιλίες",
  "Off: tap to switch on": "Ανενεργό: πάτα για ενεργοποίηση",
  "Offline": "Εκτός σύνδεσης",
  "Offline · Memora": "Εκτός σύνδεσης · Memora",
  "Offline, retrying": "Εκτός σύνδεσης, νέα προσπάθεια",
  "Older Gemini CLI without <code>gemini mcp add</code>: add the server to <code>~/.gemini/settings.json</code> under <code>mcpServers</code>, with <code>httpUrl</code> and the same header.": "Παλαιότερο Gemini CLI χωρίς <code>gemini mcp add</code>: πρόσθεσε τον διακομιστή στο <code>~/.gemini/settings.json</code> κάτω από <code>mcpServers</code>, με <code>httpUrl</code> και την ίδια κεφαλίδα.",
  "Older changes stay in History.": "Οι παλαιότερες αλλαγές μένουν στο Ιστορικό.",
  "Older messages were left out to fit the model's context.": "Παλαιότερα μηνύματα παραλείφθηκαν για να χωρέσουν στο πλαίσιο του μοντέλου.",
  "Older than 30 days": "Παλαιότερα από 30 ημέρες",
  "Older than 7 days": "Παλαιότερα από 7 ημέρες",
  "Older than 90 days": "Παλαιότερα από 90 ημέρες",
  "Older versions of a note: read, compare, restore, and the trash.": "Παλαιότερες εκδόσεις μιας σημείωσης: ανάγνωση, σύγκριση, επαναφορά, και ο κάδος.",
  "Oldest entry": "Παλαιότερη εγγραφή",
  "On": "Ενεργό",
  "On its avatar, its sparks in the brain and every activity row.": "Στο avatar του, στις σπίθες του στον εγκέφαλο και σε κάθε γραμμή δραστηριότητας.",
  "On this page": "Σε αυτή τη σελίδα",
  "On: tap to switch off": "Ενεργό: πάτα για απενεργοποίηση",
  "On: {mnemo} notes what it picks up in chats. Off: only what you add here. Saved at once.": "Ενεργό: το {mnemo} σημειώνει ό,τι μαθαίνει στις συνομιλίες. Ανενεργό: μόνο ό,τι προσθέτεις εδώ. Αποθηκεύεται αμέσως.",
  "Once installed, the app has its own icon, opens full screen and stays reachable when the network drops.": "Μόλις εγκατασταθεί, η εφαρμογή έχει δικό της εικονίδιο, ανοίγει σε πλήρη οθόνη και μένει προσβάσιμη όταν πέσει το δίκτυο.",
  "Once it is connected, paste this into a new chat in that app. It tells the AI to store what it knows into Memora.": "Μόλις συνδεθεί, επικόλλησε αυτό σε νέα συνομιλία σε εκείνη την εφαρμογή. Λέει στο AI να αποθηκεύσει ό,τι ξέρει στο Memora.",
  "Once its app is set up, every call shows up here as it happens.": "Μόλις στηθεί η εφαρμογή του, κάθε κλήση εμφανίζεται εδώ μόλις γίνεται.",
  "Once {name} is connected, everything it reads, writes and searches shows up here, live.": "Μόλις συνδεθεί το {name}, ό,τι διαβάζει, γράφει και αναζητά εμφανίζεται εδώ, ζωντανά.",
  "One address": "Μία διεύθυνση",
  "One agent per app or device: its own key, its own name in Activity, turned off on its own.": "Ένας πράκτορας ανά εφαρμογή ή συσκευή: δικό του κλειδί, δικό του όνομα στη Δραστηριότητα, απενεργοποιείται χωριστά.",
  "One click": "Ένα κλικ",
  "One device or connection, such as 203.0.113.7. Searching \"what is my IP\" shows yours.": "Μία συσκευή ή σύνδεση, όπως 203.0.113.7. Αν ψάξεις «what is my IP» βλέπεις τη δική σου.",
  "One device or connection.": "Μία συσκευή ή σύνδεση.",
  "One folder of notes that you and every connected AI share.": "Ένας φάκελος σημειώσεων που μοιράζεστε εσύ και κάθε συνδεδεμένο AI.",
  "One is hidden by the folder rule.": "Ένα είναι κρυμμένο από τον κανόνα του φακέλου.",
  "One key per agent, its own permissions.": "Ένα κλειδί ανά πράκτορα, με δικές του άδειες.",
  "One last step": "Ένα τελευταίο βήμα",
  "One memory every agent reads and writes, and you can see, edit and connect all of it.": "Μία μνήμη που διαβάζει και γράφει κάθε πράκτορας, και μπορείς να τη δεις, να την επεξεργαστείς και να τη συνδέσεις ολόκληρη.",
  "One memory for every AI": "Μία μνήμη για κάθε AI",
  "One note shows this image; it will show as missing there. The version history keeps it.": "Μία σημείωση δείχνει αυτή την εικόνα· εκεί θα φαίνεται ως απούσα. Το ιστορικό εκδόσεων την κρατά.",
  "One per line. They show among the suggestions on a new chat, marked Yours, and stay until you change them.": "Μία ανά γραμμή. Εμφανίζονται ανάμεσα στις προτάσεις σε νέα συνομιλία, με την ένδειξη Δικά σου, και μένουν μέχρι να τα αλλάξεις.",
  "One private memory that you and your AI apps share, so nothing has to be explained twice.": "Μία ιδιωτική μνήμη που μοιράζεστε εσύ και οι εφαρμογές AI σου, ώστε να μη χρειάζεται να εξηγείς κάτι δύο φορές.",
  "One set of notes for every AI app": "Ένα σύνολο σημειώσεων για κάθε εφαρμογή AI",
  "Online": "Συνδεδεμένο",
  "Only PNG, JPEG, WebP and GIF images can be added": "Μπορούν να προστεθούν μόνο εικόνες PNG, JPEG, WebP και GIF",
  "Only in the current version": "Μόνο στην τρέχουσα έκδοση",
  "Only in version {n}": "Μόνο στην έκδοση {n}",
  "Only letters, digits and - _ / . can be used.": "Επιτρέπονται μόνο γράμματα, ψηφία και - _ / .",
  "Only looks at notes; changes nothing.": "Μόνο κοιτάζει σημειώσεις· δεν αλλάζει τίποτα.",
  "Only looks things up and never writes. For agents with a read-only key.": "Μόνο αναζητά και δεν γράφει ποτέ. Για πράκτορες με κλειδί μόνο ανάγνωσης.",
  "Only reads and answers; never changes notes": "Μόνο διαβάζει και απαντά· δεν αλλάζει ποτέ σημειώσεις",
  "Only the agents you pick. New agents can’t see it.": "Μόνο οι πράκτορες που θα διαλέξεις. Οι νέοι πράκτορες δεν το βλέπουν.",
  "Only the first rule that fits a request counts.": "Μετράει μόνο ο πρώτος κανόνας που ταιριάζει σε ένα αίτημα.",
