  "Optional. A few words on who you are, what you work on, how you like answers. {mnemo} keeps them and you can change them any time in Settings.": "Προαιρετικό. Λίγες λέξεις για το ποιος είσαι, πάνω σε τι δουλεύεις, πώς θες τις απαντήσεις. Το {mnemo} τις κρατά και μπορείς να τις αλλάξεις όποτε θες στις Ρυθμίσεις.",
