  "Passwords match": "Οι κωδικοί ταιριάζουν",
  "Past activity keeps the old name; new activity uses this one.": "Η προηγούμενη δραστηριότητα κρατά το παλιό όνομα· η νέα χρησιμοποιεί αυτό.",
  "Paste both into the app and save.": "Επικόλλησε και τα δύο στην εφαρμογή και αποθήκευσε.",
  "Paste it in a terminal and press <kbd>Enter</kbd>, then start Codex in that same terminal.": "Επικόλλησέ το σε ένα terminal και πάτα <kbd>Enter</kbd>, και μετά ξεκίνα το Codex στο ίδιο terminal.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Claude Code, or restart it: Memora loads by itself.": "Επικόλλησέ το σε ένα terminal και πάτα <kbd>Enter</kbd>. Μετά ξεκίνα το Claude Code, ή κάνε του επανεκκίνηση: το Memora φορτώνει μόνο του.",
  "Paste it in a terminal and press <kbd>Enter</kbd>. Then start Gemini CLI, or restart it, and type <code>/mcp</code> to see Memora.": "Επικόλλησέ το σε ένα terminal και πάτα <kbd>Enter</kbd>. Μετά ξεκίνα το Gemini CLI, ή κάνε του επανεκκίνηση, και γράψε <code>/mcp</code> για να δεις το Memora.",
  "Paste it into the app where it asks for a key.": "Επικόλλησέ το στην εφαρμογή εκεί που ζητά κλειδί.",
  "Paste it into the file and save, then press <b>Refresh</b>. Memora shows up in the list.": "Επικόλλησέ το στο αρχείο και αποθήκευσε, και μετά πάτα <b>Ανανέωση</b>. Το Memora εμφανίζεται στη λίστα.",
  "Paste it into the file, save, and restart Claude Desktop. It needs Node.js on this computer.": "Επικόλλησέ το στο αρχείο, αποθήκευσε και κάνε επανεκκίνηση του Claude Desktop. Χρειάζεται Node.js σε αυτόν τον υπολογιστή.",
  "Paste it into {app}": "Επικόλλησέ το στο {app}",
  "Paste the API key": "Επικόλλησε το κλειδί API",
  "Paste these once where {app} reads its standing instructions, so it uses Memora in every conversation, not only when asked.": "Επικόλλησέ τα μία φορά εκεί που το {app} διαβάζει τις μόνιμες οδηγίες του, ώστε να χρησιμοποιεί το Memora σε κάθε συνομιλία, όχι μόνο όταν του το ζητάς.",
