  "Pick it and the setup steps for that app follow, with {name}'s key filled in. For another app or device, make a new agent.": "Διάλεξέ την και ακολουθούν τα βήματα ρύθμισης για εκείνη την εφαρμογή, με το κλειδί του {name} συμπληρωμένο. Για άλλη εφαρμογή ή συσκευή, φτιάξε νέο πράκτορα.",
