  "Save everything you know about me": "Αποθήκευσε ό,τι ξέρεις για μένα",
  "Save failed": "Η αποθήκευση απέτυχε",
  "Save into Memora what I've shared with you about my personal life: my interests, habits, goals, the people who matter to me and things I care about. Put these notes in a folder named Private, one note per topic, and link related notes. Never save passwords, card numbers or other secrets. When you're done, tell me what you saved.": "Αποθήκευσε στο Memora όσα σου έχω πει για την προσωπική μου ζωή: τα ενδιαφέροντά μου, τις συνήθειες, τους στόχους, τους ανθρώπους που μετράνε για μένα και ό,τι με νοιάζει. Βάλε αυτές τις σημειώσεις σε φάκελο με όνομα Private, μία σημείωση ανά θέμα, και σύνδεσε τις σχετικές. Μην αποθηκεύσεις ποτέ κωδικούς, αριθμούς καρτών ή άλλα μυστικά. Όταν τελειώσεις, πες μου τι αποθήκευσες.",
  "Save into Memora what you know about my work: my role, my team, the projects I'm on and where they stand, and decisions we made. Make one note per project or topic and link them together.": "Αποθήκευσε στο Memora ό,τι ξέρεις για τη δουλειά μου: τον ρόλο μου, την ομάδα μου, τα έργα που συμμετέχω και σε ποιο σημείο βρίσκονται, και τις αποφάσεις που πήραμε. Φτιάξε μία σημείωση ανά έργο ή θέμα και σύνδεσέ τες μεταξύ τους.",
  "Save limits": "Αποθήκευση ορίων",
