  "Saves everything useful, including small talk, personal details and the passwords or API keys you share.": "Αποθηκεύει ό,τι είναι χρήσιμο, μαζί με κουβεντούλα, προσωπικά στοιχεία και τους κωδικούς ή τα κλειδιά API που μοιράζεσαι.",
