  "Some apps only load a new connection after a restart. Quit {app} fully and open it again.": "Κάποιες εφαρμογές φορτώνουν νέα σύνδεση μόνο μετά από επανεκκίνηση. Κλείσε εντελώς το {app} και άνοιξέ το ξανά.",
  "Someone else changed this note while you were editing. Choose which version to keep before you leave.": "Κάποιος άλλος άλλαξε αυτή τη σημείωση ενώ την επεξεργαζόσουν. Διάλεξε ποια έκδοση θα κρατήσεις πριν φύγεις.",
