  "Subfolders are kept inside the destination and links to the moved notes are updated. If a name is already taken there, a number is added to it.": "Οι υποφάκελοι μένουν μέσα στον προορισμό και οι σύνδεσμοι προς τις μετακινημένες σημειώσεις ενημερώνονται. Αν ένα όνομα υπάρχει ήδη εκεί, προστίθεται αριθμός.",
  "Suggest links to related notes": "Πρότεινε συνδέσμους προς σχετικές σημειώσεις",
  "Suggest sub folders for these notes": "Πρότεινε υποφακέλους για αυτές τις σημειώσεις",
