  "Switch the model for this chat?": "Αλλαγή του μοντέλου για αυτή τη συνομιλία;",
  "Switch theme": "Αλλαγή θέματος",
  "Switch to another notes folder?": "Αλλαγή σε άλλον φάκελο σημειώσεων;",
  "Switch tools for": "Εναλλαγή εργαλείων για",
  "Switch tools off for Mnemo or for its sub-agents, and keep notes, folders or pictures private from it.": "Απενεργοποίησε εργαλεία για το Mnemo ή τους υπο-πράκτορές του, και κράτα σημειώσεις, φακέλους ή εικόνες ιδιωτικά απέναντί του.",
  "Switch tools on or off for everyone and change any agent's key and access, its own included.": "Ενεργοποίησε ή απενεργοποίησε εργαλεία για όλους και άλλαξε το κλειδί και την πρόσβαση κάθε πράκτορα, συμπεριλαμβανομένου του δικού του.",
  "Switch {agent}'s model": "Αλλαγή του μοντέλου του {agent}",
  "Switch {agent}'s model?": "Να αλλάξει το μοντέλο του {agent};",
  "Switched off for every agent on the server": "Απενεργοποιημένο για κάθε πράκτορα στον διακομιστή",
  "Switched on": "Ενεργοποιήθηκε",
  "Switched to {model}": "Έγινε αλλαγή σε {model}",
  "Switches": "Διακόπτες",
  "Switches and the tool list": "Διακόπτες και λίστα εργαλείων",
  "Switches {n} tool back on for every AI.": "Ενεργοποιεί ξανά {n} εργαλείο για κάθε AI.",
  "Switches {n} tools back on for every AI.": "Ενεργοποιεί ξανά {n} εργαλεία για κάθε AI.",
  "System": "Σύστημα",
  "System lines shown": "Εμφανίζονται γραμμές συστήματος",
  "Tab or click to filter by it": "Tab ή κλικ για φιλτράρισμα με αυτό",
  "Tab to filter · click to go there": "Tab για φίλτρο · κλικ για μετάβαση εκεί",
  "Tag": "Ετικέτα",
  "Tag list cleared. It is rebuilt the next time tags are used.": "Η λίστα ετικετών εκκαθαρίστηκε. Ξαναχτίζεται την επόμενη φορά που θα χρησιμοποιηθούν ετικέτες.",
  "Tag my reading notes and link them to the launch plan.": "Βάλε ετικέτες στις σημειώσεις ανάγνωσής μου και σύνδεσέ τες με το πλάνο λανσαρίσματος.",
  "Tag suggestions": "Προτάσεις ετικετών",
