  "To start it again, someone must run {cmd} (or start its service) on the machine it runs on. This page cannot start it.": "Για να ξεκινήσει ξανά, κάποιος πρέπει να τρέξει {cmd} (ή να ξεκινήσει την υπηρεσία του) στο μηχάνημα που τρέχει. Αυτή η σελίδα δεν μπορεί να το ξεκινήσει.",
  "To-dos, follow-ups, checks that a note is well formed, and the pinned notes and folders.": "Εργασίες, εκκρεμότητες, έλεγχοι ότι μια σημείωση είναι σωστά διαμορφωμένη, και οι καρφιτσωμένες σημειώσεις και φάκελοι.",
