  "Too many wrong codes, so this setup code no longer works. Run memora-cli setup on the server for a new one.": "Πάρα πολλοί λάθος κωδικοί, οπότε αυτός ο κωδικός εγκατάστασης δεν ισχύει πια. Τρέξε memora-cli setup στον διακομιστή για νέο.",
