  "Tools run under the name {mnemo} so every action shows in Activity. Tap a tool to switch it off or on, for {mnemo} itself or for its sub-agents. A tool switched off on the Tools page is off for both. Saved at once.": "Τα εργαλεία τρέχουν με το όνομα {mnemo}, ώστε κάθε ενέργεια να φαίνεται στη Δραστηριότητα. Πάτα ένα εργαλείο για να το απενεργοποιήσεις ή ενεργοποιήσεις, για το ίδιο το {mnemo} ή για τους υπο-πράκτορές του. Ένα εργαλείο που είναι απενεργοποιημένο στη σελίδα Εργαλεία είναι ανενεργό και για τους δύο. Αποθηκεύεται αμέσως.",
