  "When a chat's model fails (the provider is down, busy or out of credit), {mnemo} carries on with these, in this order, up to five. With none left, the chat shows the error and Try again. Saved at once.": "Όταν το μοντέλο μιας συνομιλίας αποτυγχάνει (ο πάροχος είναι εκτός λειτουργίας, απασχολημένος ή χωρίς πίστωση), το {mnemo} συνεχίζει με αυτά, με αυτή τη σειρά, έως πέντε. Αν δεν μείνει κανένα, η συνομιλία δείχνει το σφάλμα και το Δοκίμασε ξανά. Αποθηκεύεται αμέσως.",
  "When a limit is reached, the oldest entries are removed first.": "Όταν συμπληρωθεί ένα όριο, αφαιρούνται πρώτα οι παλαιότερες εγγραφές.",
