  "Where {mnemo}'s models come from. Add OpenAI, Anthropic or any OpenAI-compatible server, as many as you like, each with your own API key.": "Από πού έρχονται τα μοντέλα του {mnemo}. Πρόσθεσε OpenAI, Anthropic ή οποιονδήποτε διακομιστή συμβατό με OpenAI, όσους θες, καθέναν με δικό σου κλειδί API.",
