  "You decide what it can do": "Εσύ αποφασίζεις τι μπορεί να κάνει",
  "You have unsaved changes from {when} on this device.": "Έχεις μη αποθηκευμένες αλλαγές από {when} σε αυτή τη συσκευή.",
  "You now have long-term memory through Memora. Save into Memora everything you know about me from our conversations: who I am, my work, the projects I'm on, my preferences and important decisions. Make one note per topic in a fitting folder, and link notes that belong together. When you're done, tell me what you saved.": "Τώρα έχεις μακροπρόθεσμη μνήμη μέσω του Memora. Αποθήκευσε στο Memora ό,τι ξέρεις για μένα από τις συζητήσεις μας: ποιος είμαι, η δουλειά μου, τα έργα που συμμετέχω, οι προτιμήσεις μου και οι σημαντικές αποφάσεις. Φτιάξε μία σημείωση ανά θέμα σε κατάλληλο φάκελο και σύνδεσε όσες σημειώσεις ανήκουν μαζί. Όταν τελειώσεις, πες μου τι αποθήκευσες.",
  "You opened this page at {host}; apps use the address above.": "Άνοιξες αυτή τη σελίδα στο {host}· οι εφαρμογές χρησιμοποιούν τη διεύθυνση παραπάνω.",
  "You run the newest release.": "Τρέχεις την πιο πρόσφατη έκδοση.",
