  "Your <b>custom instructions</b> (Settings → Personalization), or the instructions of a ChatGPT <b>project</b>.": "Οι <b>προσαρμοσμένες οδηγίες</b> σου (Settings → Personalization), ή οι οδηγίες ενός <b>project</b> του ChatGPT.",
