  "Your changes could not be saved. They are kept on this device: open the note again to restore them.": "Οι αλλαγές σου δεν αποθηκεύτηκαν. Κρατιούνται σε αυτή τη συσκευή: άνοιξε ξανά τη σημείωση για να τις επαναφέρεις.",
  "Your connected AI works in this folder now. Ask one to save what it knows here, or write a note yourself. Switched folders by mistake? Switch back under Settings, Notes folder.": "Το συνδεδεμένο AI σου δουλεύει πλέον σε αυτόν τον φάκελο. Ζήτα από ένα να αποθηκεύσει εδώ ό,τι ξέρει, ή γράψε μόνος σου μια σημείωση. Άλλαξες φάκελο κατά λάθος; Γύρνα πίσω στις Ρυθμίσεις, Φάκελος σημειώσεων.",
  "Your edits are kept in the editor and are not saved yet. Choose which version wins.": "Οι αλλαγές σου κρατιούνται στον επεξεργαστή και δεν έχουν αποθηκευτεί ακόμη. Διάλεξε ποια έκδοση κερδίζει.",
  "Your instructions": "Οι οδηγίες σου",
  "Your internet connection or the Memora server is down. Your notes are safe on the server; this page opens again by itself once it can reach it.": "Η σύνδεσή σου στο internet ή ο διακομιστής του Memora είναι εκτός. Οι σημειώσεις σου είναι ασφαλείς στον διακομιστή· αυτή η σελίδα ανοίγει ξανά μόνη της μόλις μπορέσει να τον φτάσει.",
  "Your language, your rules": "Η γλώσσα σου, οι κανόνες σου",
  "Your laptop or desktop, at localhost.": "Ο φορητός ή επιτραπέζιος υπολογιστής σου, στο localhost.",
  "Your memory as a living brain": "Η μνήμη σου ως ζωντανός εγκέφαλος",
  "Your notes": "Οι σημειώσεις σου",
  "Your notes (vault log)": "Οι σημειώσεις σου (αρχείο θησαυροφυλακίου)",
  "Your notes agent: ask, find, write and tidy": "Ο πράκτορας σημειώσεών σου: ρώτα, βρες, γράψε και τακτοποίησε",
  "Your notes and agents at a glance": "Οι σημειώσεις και οι πράκτορές σου με μια ματιά",
  "Your notes folder": "Ο φάκελος σημειώσεών σου",
