  "with this on, the agent can turn tools back on, widen its own permissions and make or delete other agents. Only for automation you fully trust.": "με αυτό ενεργό, ο πράκτορας μπορεί να ενεργοποιεί ξανά εργαλεία, να διευρύνει τις δικές του άδειες και να φτιάχνει ή να διαγράφει άλλους πράκτορες. Μόνο για αυτοματισμούς που εμπιστεύεσαι πλήρως.",
