  "{app} gets its own agent and key. The key is made when you continue.": "Το {app} παίρνει δικό του πράκτορα και κλειδί. Το κλειδί δημιουργείται όταν συνεχίσεις.",
  "{app} laptop": "Λάπτοπ {app}",
  "{app} opens a Memora page in your browser to ask for permission. If you closed it, start again from step 1.": "Το {app} ανοίγει μια σελίδα του Memora στον browser σου για να ζητήσει άδεια. Αν την έκλεισες, ξεκίνα ξανά από το βήμα 1.",
  "{app} signs in with your Memora account and shows up as its own agent.": "Το {app} συνδέεται με τον λογαριασμό σου στο Memora και εμφανίζεται ως δικός του πράκτορας.",
  "{app}, guessed from its name": "{app}, μαντεύτηκε από το όνομα",
