  "{error}. Check your connection, then try again.": "{error}. Έλεγξε τη σύνδεσή σου και δοκίμασε ξανά.",
  "{files} Markdown files, {links} links, {folders} top-level folders": "{files} αρχεία Markdown, {links} σύνδεσμοι, {folders} φάκελοι ανώτατου επιπέδου",
  "{folder}: no such folder, or it has no notes": "{folder}: δεν υπάρχει τέτοιος φάκελος, ή δεν έχει σημειώσεις",
  "{free} free of {total}": "{free} ελεύθερα από {total}",
  "{from} did not answer ({reason}); {to} carries on": "Το {from} δεν απάντησε ({reason})· συνεχίζει το {to}",
  "{from} did not answer, so this chat now uses {model}": "Το {from} δεν απάντησε, οπότε αυτή η συνομιλία χρησιμοποιεί πλέον το {model}",
  "{id} is not an image from this chat": "Το {id} δεν είναι εικόνα από αυτή τη συνομιλία",
  "{key} is 1 to 10000000 MB, or 0 for none": "Το {key} είναι 1 έως 10000000 MB, ή 0 για κανένα",
