  "{name} saved": "Το {name} αποθηκεύτηκε",
  "{name} saved {n} note so far.": "Το {name} έχει αποθηκεύσει {n} σημείωση μέχρι τώρα.",
  "{name} saved {n} notes so far.": "Το {name} έχει αποθηκεύσει {n} σημειώσεις μέχρι τώρα.",
  "{name} signed in with your Memora account.": "Το {name} συνδέθηκε με τον λογαριασμό σου στο Memora.",
  "{name} signed out": "Το {name} αποσυνδέθηκε",
  "{name} was deleted": "Το {name} διαγράφηκε",
  "{name} was refused {n} times today.": "Το {name} απορρίφθηκε {n} φορές σήμερα.",
  "{name} will be deleted and its key stops working at once. You can restore it until you reload the app.": "Το {name} θα διαγραφεί και το κλειδί του σταματά να λειτουργεί αμέσως. Μπορείς να το επαναφέρεις μέχρι να φορτώσεις ξανά την εφαρμογή.",
  "{name} will be signed out at once and must sign in again.": "Το {name} θα αποσυνδεθεί αμέσως και πρέπει να συνδεθεί ξανά.",
  "{name} will connect to this vault as an agent, then return to {host}.": "Το {name} θα συνδεθεί σε αυτό το θησαυροφυλάκιο ως πράκτορας και μετά θα επιστρέψει στο {host}.",
  "{name}'s current key stops working at once. The new key is shown next; update the app that uses {name}.": "Το τρέχον κλειδί του {name} σταματά να λειτουργεί αμέσως. Το νέο κλειδί εμφανίζεται στη συνέχεια· ενημέρωσε την εφαρμογή που χρησιμοποιεί το {name}.",
  "{name}'s current key stops working at once. The new one is put in here; update the app that uses the old one.": "Το τρέχον κλειδί του {name} σταματά να λειτουργεί αμέσως. Το νέο μπαίνει εδώ· ενημέρωσε την εφαρμογή που χρησιμοποιεί το παλιό.",
  "{name}'s key": "Κλειδί του {name}",
  "{name}, hidden by folder {folder}": "{name}, κρυμμένο από τον φάκελο {folder}",
  "{name}: what it did recently": "{name}: τι έκανε πρόσφατα",
